window.ROOTLAB_BILINGUAL_HISTORY={"access":{"en":"From Middle English accesse, acces, borrowed from Middle French acces (“attack, onslaught”) or from its source Latin accessus, perfect passive participle of accēdō","zh":"从中英的入口,cces,借自中法的cces (\"攻击,攻击\")或其源拉丁的入口, 完美的被动 participle of acc ⁇ d ⁇","translation":"machine"},"admission":{"en":"Borrowed from Latin admissio, admissionis; compare French admission. See admit.","zh":"借用拉丁语副词,certificis; 比较法国语的certification.请参看certifications.","translation":"machine"},"admit":{"en":"From Middle English admitten, amitten, borrowed from Old French admettre, amettre (“to admit”), from Latin admittō (“to allow entrance, inlet”, literally “to send","zh":"从中英的承认, Amitten, 借自老法的admettre, amettre (\"承认\"),从拉丁的承认 (\"允许进入, 输入\"), 字面意思是\"发送\"","translation":"machine"},"advocate":{"en":"From Middle English advocat, advoket, from Old French advocat, from Latin advocātus (“an advocate”), from the substantivization of the perfect passive participle of","zh":"从中英代言人,代言人,从老法兰西代言人,从拉丁代言人(一个代言人),从潜伏的 完美被动的 Participle of","translation":"machine"},"allocate":{"en":"From Middle English allocate (the common first word of writs authorizing payment), from Medieval Latin allocātum, substantivized from the nominative neuter singular of","zh":"从中英文分配(授权支付令令的常见第一字),从中世纪拉丁语 alocātum,从命名的阴极单数中被子化","translation":"machine"},"allocation":{"en":"From Middle French allocacion, from Medieval Latin allocātiō. By surface analysis, allocate + -ion.","zh":"由中法的alocacion,中世纪的拉丁语alocātiā.通过表面分析,分配+−离子.","translation":"machine"},"anachronism":{"en":"From New Latin anachronismus, from Ancient Greek ἀναχρονισμός (anakhronismós), from ἀναχρονίζομαι (anakhronízomai, “referring to the wrong time”), from ἀνά (aná, “up against”) +","zh":"出自新拉丁时代,古希腊语(anakhronismós),阿纳赫罗尼佐迈语(aakhronízomai,“反向错误时间”),自QQ(Aná,“上反”)+","translation":"machine"},"aquaculture":{"en":"From aqua- + culture.","zh":"从aqua-+文化.","translation":"machine"},"aquamarine":{"en":"From Latin aqua marīna (“sea water”), adjective form from mare (“sea”).","zh":"从拉丁语aqua mar ⁇ na (\"海水\"),形容词形式从mare (\"海洋\").","translation":"machine"},"aquarium":{"en":"Borrowed from Latin aquārium, neuter of aquārius (“of or pertaining to water”), from aqua + -arium. Doublet of ewer; see also Aquarius. Also","zh":"借用自拉丁语aquārium, aquārius的子宫( \" of或与水有关 \" ),aqua +-arium. Doublet of ewer;另见Aquarius。","translation":"machine"},"aquatic":{"en":"Borrowed from Middle French aquatique (“living in water”), from Latin aquaticus (“relating to water”), from aqua (“water”).","zh":"借用自中法水系(“生活在水中”),拉丁水系(“与水有关”),水系(“水”)。","translation":"machine"},"aqueous":{"en":"Formed from Latin aqua + -ous (or from Medieval Latin aqueus), partly the analogy of Middle French aqueux (itself actually from Latin aquosus).","zh":"由拉丁语aqua + -ous(或中世纪拉丁语aquus)形成,部分是中法语aqueux的类比(它本身实际上来自拉丁语aquosus).","translation":"machine"},"aquifer":{"en":"From aqui- + -fer.","zh":"从aqui - + - fer.","translation":"machine"},"asynchronous":{"en":"From a- + synchronous.","zh":"从a-+同步.","translation":"machine"},"attract":{"en":"From Latin attractus, past participle of attrahere (“to draw to, attract”), from ad (“to”) + trahere (“to draw”).","zh":"从拉丁语的吸引语,过去 Attrahere 的 participle (“要吸引,要吸引”),从 ad (“要”) + trahere (“要吸引)).","translation":"machine"},"attraction":{"en":"From Middle English attraccioun, from Old French attraction, from Latin attractio from past participle of attrahō (= ad + trahō), equivalent to attract","zh":"从中英文attraccioun, 旧法语吸引,从拉丁语吸引从过去 participle of attrah ⁇ (= ad + trah ⁇ ), 相当于吸引","translation":"machine"},"attractive":{"en":"From Middle French attractif, from Late Latin attractīvus, equivalent to attract + -ive.","zh":"从中法语吸引语,从拉丁语吸引语,相当于吸引语 + -ive.","translation":"machine"},"audible":{"en":"Borrowed from Middle French audible, from Late Latin audibilis, from Latin audire (“to hear”).","zh":"借自中法音译,后拉丁音译,拉丁音译音译(\"听\").","translation":"machine"},"audience":{"en":"From Middle English audience, from Middle French audience, from Old French audience, from Latin audientia, from present participle audiēns (“hearing”), from verb audiō","zh":"从中英观众,从中法观众,从老法兰西观众,从拉丁语听觉,从现在的participle audiens (\"hearing\"),从动词audi ⁇ .","translation":"machine"},"audition":{"en":"Borrowed from Middle French audicion, from Latin audītiō, from audiō (“to hear”).","zh":"借自中法学者、拉丁学者、学者(“听话”)","translation":"machine"},"auditorium":{"en":"Borrowed from Latin audītōrium, from audītōrius (“pertaining to hearing”). Equivalent to auditory + -ium.","zh":"借用自拉丁语aud ⁇ t ⁇ rium,从aud ⁇ t ⁇ rius (\"涉及听力\"),等同于听力+− ⁇ .","translation":"machine"},"auditory":{"en":"Borrowed from Latin audītōrius (“pertaining to a hearer or hearing”), from audiō (“to hear”) + -tōrius (“-tory”, adjectival suffix).","zh":"借用拉丁语audítōrius(“涉及听力或听力”), 借用拉丁语 + -tārius(“-tory”,形容词后缀)。","translation":"machine"},"autobiography":{"en":"From auto- + biography.","zh":"从自动+传记.","translation":"machine"},"autofocus":{"en":"From auto- + focus.","zh":"从自动 - + 聚焦。","translation":"machine"},"autograph":{"en":"From Latin autographum, in turn from Ancient Greek αὐτόγραφον (autógraphon, “a writing in one’s own hand”). Equivalent to auto- + -graph.","zh":"从拉丁语签名,转而从古希腊语(autógraphon, \" 自己手写 \" ) 。 等价到自动+-graph。","translation":"machine"},"automatic":{"en":"Borrowed from New Latin automaticus, from Classical Latin automatum (“automaton”) + -icus (adjectival suffix), from Ancient Greek αὐτόματον (autómaton), neuter of αὐτόματος (autómatos,","zh":"借用自新拉丁语自动语,古典拉丁语自动语(“automaton”)+-icus(形容后缀),古希腊语(autómaton), neuter of ⁇ (autómatos,","translation":"machine"},"automation":{"en":"From automatic + -ion or automaton + -ion; coined by a Ford Executive Vice President, Delmar S. Harder, in the 1940s.","zh":"从自动+−离子或自动马顿+−离子;由福特执行副总裁Delmar S. Harder于1940年代铸造.","translation":"machine"},"automobile":{"en":"From French automobile, from Ancient Greek αὐτός (autós, “self”) + French mobile (“moving”), from Latin mōbilis (“movable”), equivalent to auto- (“self”) + mobile.","zh":"从法国汽车,从古希腊汽车(autós,“self”)+法国移动(“移动”),从拉丁语m ⁇ bilis (“可移动”),相当于汽车(“self”) + 移动。","translation":"machine"},"autonomous":{"en":"From autonomy + -ous.","zh":"从自主+− ⁇ .","translation":"machine"},"autonomy":{"en":"Borrowed from Ancient Greek αὐτονομῐ́ᾱ (autonomĭ́ā, “freedom to use its own laws, independence”), from αὐτόνομος (autónomos, “living under one's own laws, independent”) +","zh":"借用自古希腊语 ⁇ (autonom ⁇ ,“自由使用自己的法律,独立”),借用自 ⁇ (autónomos,“根据自己的法律生活,独立”) +","translation":"machine"},"bankrupt":{"en":"Partial calque of Italian bancarotta (literally “a broken bench”), from banca (“bank”, literally “bench”) + rotta (“broken, rupted”), which refers to an out-of-business","zh":"意大利班卡罗塔(字面意思是“断板凳”)的部分口径,来自班卡(“银行”,字面意思是 “bench”) + rotta(“broken, rupted”),指营业外","translation":"machine"},"benediction":{"en":"From Middle English benediccion, from Ecclesiastical Latin benedictio, benedictionis, from benedictus (“blessed; well spoken of”). Doublet of benison.","zh":"从中英语benediccion,从拉丁语benedigitio, benedictis,从贝内迪克图斯 (“blested; well speak of”). Doublet of Benison.","translation":"machine"},"benefactor":{"en":"From Middle English benefactor, borrowed from Medieval Latin benefactor (“he who bestows a favor”), from Latin benefaciō (“benefit someone”), from bene (“good”) +","zh":"从中英的恩人,借自中世纪的拉丁恩人(“恩人”),借自拉丁语的恩人(“好处某人”),借自Bene (“好人”)+","translation":"machine"},"beneficial":{"en":"From Late Latin beneficiālis (“beneficial”), from Latin beneficium (“benefit, favor, kindness”).","zh":"来源于Late Latin beneficiālis (\"beneficial\"),来源于拉丁语 beneficium (\"好处,恩惠,善良\").","translation":"machine"},"beneficiary":{"en":"From Latin beneficiarius (“enjoying a favor, granted a privilege”) from beneficium (“benefit”), perhaps via or influenced by French bénéficiaire (“beneficiary”). Indirectly, by way","zh":"从拉丁语beneficiarius (“享受恩惠,获得特权”)从beneficiaum (“好处”), 可能通过或受法国bénéficiaire (“受益者”) 的影响。","translation":"machine"},"benefit":{"en":"From Late Middle English benefytt, benefett, alteration (due to Latin bene-) of benfet, bienfet, bienfait (“good or noble deed”), from Anglo-Norman benfet (“well-done”),","zh":"从中世纪晚期英语Benefyt, Benefett, 改变(由于拉丁语Bene-)Benfet, bienfet, bienfait (\"好或高尚的契约\"),从盎格鲁-诺曼语Benfet (\"well-done\"),","translation":"machine"},"benevolence":{"en":"Circa 1400, original sense “good will, disposition to do good”, Old French benivolence from Latin benevolentia (also directly from Latin), literally “good will”,","zh":"Circa 1400,原意为\"善意,服从于行善\",旧法式仁慈来自拉丁语的仁爱(也直接来自拉丁语),字面意思为\"善意\",\"善良\".","translation":"machine"},"benevolent":{"en":"From Old French benevolent, borrowed from Latin benevolēns (\"benevolent\"). Displaced native Old English welwillende (literally well-wishing).","zh":"从旧法式慈悲,借自拉丁文的慈悲(\"慈悲\"),流离失所的本土老英语Welwillende(字面意思是好).","translation":"machine"},"biodegradable":{"en":"From bio- + degradable.","zh":"从生物-+可降解.","translation":"machine"},"biography":{"en":"Borrowed from New Latin biographia, from Ancient Greek βιογραφίᾱ (biographíā), from βίος (bíos, life) + -γραφία (-graphía, writing).","zh":"借用自新拉丁语传记,古希腊语(英语:Ancient Greek QQ (biograph)),来自 ⁇ (bíos, life)+- ⁇ (-graphía,写作).","translation":"machine"},"biological":{"en":"From biology + -ical.","zh":"从生物学+ - 理论.","translation":"machine"},"bioluminescence":{"en":"From bio- + luminescence.","zh":"从生物-+发光.","translation":"machine"},"biosphere":{"en":"Borrowed from German Biosphäre, coined by Austrian geologist Eduard Suess in 1875. By surface analysis, bio- + -sphere.","zh":"从德国Biosphäre借来的,1875年由奥地利地质学家爱德华·苏斯(Eduard Sues)铸币,通过表面分析,生物-+-圈.","translation":"machine"},"biotechnology":{"en":"From bio- + technology.","zh":"从生物+技术.","translation":"machine"},"chronic":{"en":"From chronical, from Old French cronike, from Latin chronicus, from Ancient Greek χρονικός (khronikós, “of time”), from χρόνος (khrónos, “time”). By surface analysis,","zh":"从编年史,从旧法国的cronike,从拉丁的编年史,从古希腊的 ⁇ (khronikós,“of time ”),从 ⁇ (khrónos,“time ” ),从表面分析,","translation":"machine"},"chronicle":{"en":"From Middle English cronicle, cronycle, from Anglo-Norman cronicle, from Old French cronike, from Latin chronica, from Ancient Greek χρονικός (khronikós, “of or concerning","zh":"从中英的胸骨, 胸骨,从盎格鲁-诺曼的胸骨,从旧法国的胸骨,从拉丁语的慢性,从古希腊语的 ⁇ ( khronikós, “of or commission)","translation":"machine"},"chronological":{"en":"From chrono- + -logical or chronology + -ical.","zh":"从chrono - + - 逻辑学或编年法 + - ical.","translation":"machine"},"chronology":{"en":"From chrono- (“relating to time”) + -logy (“study of, account of”), after New Latin chronologia from Ancient Greek χρόνος (khrónos, “time”) + λόγος","zh":"从chrono-(“关系与时间”)+- 学 (“研究,核算”), 取自古希腊语的新拉丁语编年史 ⁇ (khrónos,“时间”)+ ⁇","translation":"machine"},"commit":{"en":"Inherited from Middle English committen, itself borrowed from Latin committō (“to bring together, join, compare, commit (a wrong), incur, give in charge, etc.”),","zh":"继承自中英承诺,本身借用自拉丁承诺(“合并、加入、比较、实施(错误)、承担、负责等”),","translation":"machine"},"concede":{"en":"From Middle English [Term?], from Old French conceder, from Latin concēdō (“give way, yield”), from con- (“wholly”) + cēdō (“to yield, give way,","zh":"从中英文[Term?],从旧法兰西语的收录者,从拉丁语的收录(\"give way, limit\"),从康语的收录(“whyly] + c ⁇ d ⁇ (\"to elimit, off way,,\"","translation":"machine"},"conduct":{"en":"From Late Latin conductus (“defense, escort”), from Latin conductus, perfect passive participle of condūcō (“bring together”); see also conduce. Displaced native Old English","zh":"从拉丁语的后期行为(“防卫,护卫”),从拉丁语的后继行为, 完美的被动的cond ⁇ c ⁇ (“共同”); 另见 conduce。","translation":"machine"},"conductor":{"en":"Borrowed from Middle French conductour, from Old French conduitor, from Latin conductor.","zh":"借用自中法导师,旧法导师,拉丁导师.","translation":"machine"},"conform":{"en":"From Middle English conformen, borrowed from Middle French and Anglo-Norman conformer, from Latin conformāre (“to mould, to shape after”).","zh":"从中英文科借入中法文科和盎格鲁-诺尔曼科借入拉丁文科借入( \" 至模具,在后成型 \" )。","translation":"machine"},"construct":{"en":"Borrowed from Latin cōnstrūctus, from cōnstruō (“to heap together”), from com- (“together”) + struō (“to heap up, pile”). Doublet of construe.","zh":"借自拉丁文c ⁇ nstr ⁇ ctus,从c ⁇ nstru ⁇ (\"合起来\"),从com- (\"合在一起\") + stru ⁇ ((\"堆起来,堆起来\")) , 双重解释。","translation":"machine"},"construction":{"en":"From Middle English construccioun, construction, from Old French construction, from Latin cōnstructiō, from cōnstruere. Morphologically construct + -ion.","zh":"从中英算术,建筑学,旧法兰西建筑学,拉丁语c ⁇ nstructi ⁇ ,C ⁇ nstrure. Morphological building + -ion.","translation":"machine"},"constructive":{"en":"From Latin cōnstrūctīvus. By surface analysis, construct + -ive.","zh":"从拉丁文c ⁇ nstr ⁇ ct ⁇ vus.通过表面分析,构造+−ive.","translation":"machine"},"contract":{"en":"From Middle English, from Middle French contracter, from Latin contractum, past participle of contrahere (“to bring together, to bring about, to conclude a","zh":"从中英,从中法合同商,从拉丁语合同商,过去 participle of contrahere (“召集、促成、缔结......","translation":"machine"},"contraction":{"en":"PIE word *ḱóm From Late Middle English contraccioun, contraxion (“spasm, contraction; constriction, shrinking; act of pressing together”), from Old French contraction (modern French","zh":"PIE词 ⁇ m从中晚期英语 contraccion, contraxion (\"spasm, craxion, crax, crashing, compact of compensive\"),来自旧法式收缩(现代法语).","translation":"machine"},"contradict":{"en":"Derived from Latin contrādictus (“contradicted”), the past participle of contrādīcō (“speak against”) (originally two words).","zh":"来源于拉丁文contrādictus (“有争议”),即过去contrād ⁇ c ⁇ (“speak against”) (原为两个单词)的participle of contrād ⁇ c ⁇ (“sword against”).","translation":"machine"},"contradiction":{"en":"From Middle English contradiccioun, contradiction, from Old French contradiction, from Latin contrādictiō, from contrādīcō (“speak against”).","zh":"从中英反,矛盾,从旧法式矛盾,从拉丁语contrādictiā,从contrād ⁇ c ⁇ (\"Speak for against\").","translation":"machine"},"corrupt":{"en":"From Middle English corrupten, derived from Latin corruptus, past participle of corrumpō (“to destroy, ruin, injure, spoil, corrupt, bribe”), from com- (“together”) +","zh":"源自中英腐败,源自拉丁腐败,过去corrump ⁇ (\"破坏,毁灭,伤害,破坏,腐化,贿赂\"),来自com-(\"联合\")+","translation":"machine"},"corruption":{"en":"Borrowed from French corruption, from Latin corruptiō, equivalent to corrupt + -ion.","zh":"借自法国腐败,拉丁腐败,相当于腐败+−离子.","translation":"machine"},"credential":{"en":"From Medieval Latin crēdentiālis (“giving authority”), from Latin crēdentia (“trust”).","zh":"来源于中世纪拉丁语crädentiālis (\"授意权威\"),来源于拉丁语cr ⁇ dentia (\"托拉斯\").","translation":"machine"},"credibility":{"en":"Borrowed from French crédibilité, from Medieval Latin credibilitas, from Latin credibilis. By surface analysis, credible + -ity.","zh":"借用自法国的crédibilité,中世纪拉丁语credibilitas,拉丁语credibilis.通过表面分析,可信+-ity.","translation":"machine"},"credible":{"en":"From Middle English credible, borrowed from Middle French credible, from Latin crēdibilis (“worthy of belief”), from crēdō (“believe”); see credit.","zh":"从中英可信、从中法可信、从拉丁语crêdibilis ( \" 值得相信 \" ) 、从cr ⁇ d ⁇ ( \" 相信 \" )中借来的;见信用。","translation":"machine"},"credit":{"en":"Borrowed from Middle French crédit (“belief, trust”), from Latin crēditum (“a loan, credit”), neuter of crēditus, past participle of crēdere (“to believe”). The","zh":"借用自中法的crédit(“信仰,信托”),拉丁语cr ⁇ ditum(“贷款,信贷”),nuter of cr ⁇ ditus, 以往的cr ⁇ dere(“相信”) 。","translation":"machine"},"creditor":{"en":"From Middle English creditour, from Anglo-Norman creditour, from Latin crēditor, from crēditum (“loan”), from crēditus, perfect passive participle of crēdō (“lend”).","zh":"从中英信用,从盎格鲁-诺曼信用,从拉丁语cräditor,从cr ⁇ ditum (\"loan\"),从crıditus, 完美被动的cr ⁇ d ⁇ (\"lend\") 中.","translation":"machine"},"credulous":{"en":"Originated in 1576, borrowed from Latin crēdulus (“that easily believes a thing, credulous”), from crēdō (“I believe”).","zh":"起源于1576年,借自拉丁语credulus(\"容易相信某件事,可信\"),借自credō(\"我相信\").","translation":"machine"},"creed":{"en":"Inherited from Middle English crede, from Old English crēda, borrowed from Latin crēdō (“to believe”), from Proto-Italic *kresdō, from Proto-Indo-European *ḱréddʰeh₁ti (“to believe,","zh":"继承自中英信德,老英信德,借自拉丁信德,借于普罗托-意大利语*kresd ⁇ ,借于普洛托-印度-欧洲语* ⁇ rédheh1ti (\"要相信,","translation":"machine"},"cycle":{"en":"From Middle English cicle (“fixed length period of years”), from Late Latin cyclus, from Ancient Greek κύκλος (kúklos, “circle”), from Proto-Hellenic *kúklos, *kʷókʷlos,","zh":"从中英冰(“固定的长度期”),从晚拉丁囊括语,从古希腊语(kúklos,“circle”),从Proto-Hellenic*kúklos ,*kwókwlos,","translation":"machine"},"cyclic":{"en":"From French cyclique or its etymon Classical Latin cyclicus, from Ancient Greek κυκλικός (kuklikós). By surface analysis, cycle + -ic. Piecewise doublet of","zh":"来源于法国环形山或它的齿状古典拉丁环形山,来源于古希腊语 ⁇ (kuklikós),通过表面分析,循环+-ic. piecwise deplit of","translation":"machine"},"cyclist":{"en":"From cycle + -ist, 1882.","zh":"从周期 + - ist, 1882.","translation":"machine"},"deduce":{"en":"From Late Middle English deducen (“to demonstrate, prove, show; to argue, infer; to bring, lead; to turn (something) to a use; to deduct”),","zh":"从中晚期英语推论(“以证明、证明、显示、论证、推论、引领、转作某种用途、推算),","translation":"machine"},"deduction":{"en":"From Middle French déduction, from Latin deductio. Equivalent to deduct + -ion or deduce + -tion.","zh":"从中法语的déenduction,从拉丁语的dectionio. 等值可以扣除+− ion或 deduce + -tion.","translation":"machine"},"deflect":{"en":"From Latin deflecto, from de- (“away”) + flecto (“to bend”).","zh":"从拉丁语偏移,从脱(“away”) + flecto (“to band”).","translation":"machine"},"deflection":{"en":"From Latin dēflexiō, from dēflectere (“to deflect”; participle stem dēflex-) + -iō (suffix forming abstract nouns). The non-etymological spelling deflection is taken from","zh":"从拉丁语 d ⁇ flexi ⁇ ,从d ⁇ flexere (\"to diffect; participlestand d ⁇ fles-\") + -i ⁇ (后缀形成抽象名词) 中取自非语言性拼音的diffect.","translation":"machine"},"deform":{"en":"From Middle English deforme (“out of shape, deformed”) [and other forms], from Middle French deforme (modern French difforme (“misshapen, deformed”)), or directly from","zh":"从中英变形(“外形,变形”)[和其他形式],从中法变形(现代法国变形(“misshapen,变形”)),或直接从.","translation":"machine"},"deport":{"en":"Borrowed from French déporter. With the meaning of \"behave\", from Old French deporter (“behave”), from Latin deportō, from de- + portō.","zh":"借用自法国的déporter,意思是\"行为\",来自旧法国的驱逐者(“行为”),来自拉丁语的驱逐者,来自de- +port ⁇ .","translation":"machine"},"describe":{"en":"From Middle English descriven, from Old French descrivre, from Latin dēscrībō (“to copy off, transcribe, sketch off, describe in painting or writing”), from","zh":"从中英文 descriven,从旧法语 descrivre,从拉丁语 dêscribe b ⁇ ( (“抄写, 转写,草图,在绘画或写作中描述”),从","translation":"machine"},"description":{"en":"From Middle English descripcioun, from Old French description and its etymon, Latin dēscrīptiō, noun of action of dēscrībō (“to describe”). Equivalent to describe","zh":"从中英文 descripcioun,从旧法语描述及其词条, 拉丁语 d ⁇ scr ⁇ pti ⁇ , 代词 d ⁇ scrib ⁇ (\"to scription\"). Equivality to scripte.","translation":"machine"},"descriptive":{"en":"From Latin dēscriptīvus (“containing a full description”).","zh":"从拉丁文d ⁇ scriptívus ((包含完整描述)).","translation":"machine"},"diameter":{"en":"From Old French diametre (French diamètre), from Latin diametros, from Ancient Greek διάμετρος (diámetros) (γραμμή (grammḗ)) (diametros grammē, “line measuring across”), from διά","zh":"来源于旧法语diamètre(法语diamètre),拉丁语diametros(法语diametros),古希腊语 ⁇ (法语diamteros),(法语gramm ⁇ ),(法语damteros gramm ⁇ ,“横线测量”),来自 ⁇ (法语),","translation":"machine"},"dictator":{"en":"Borrowed from Latin dictātor (“a chief magistrate”), from dictō (“dictate, prescribe”), from dīcō (“say, speak”). By surface analysis, dictate + -or, literally “one","zh":"从拉丁语dictātor(“首席地方法官”)、dictā(“指定,处方”)、d ⁇ cāsay(“say, speak”)借来的。","translation":"machine"},"diction":{"en":"From late Middle English diccion (“something said; a word or phrase”) (an obsolete sense in Modern English), borrowed directly from Latin dictiō (“a","zh":"从后期的中英文词条( \" 某事说;一个词或短语 \" )(现代英语中的一种过时的词句)直接借用自拉丁文词条( \" a \" )","translation":"machine"},"dictionary":{"en":"From Middle English dixionare, a learned borrowing from Medieval Latin dictiōnārium, from Latin dictiōnārius, from dictiō (“a speaking”), from dictus, perfect past participle","zh":"从中世纪拉丁语ditiōnārium,从拉丁语dittiōnārius,从diti ⁇ (“a speaking”),从ditus, 完美过去 participle 的学习借款。","translation":"machine"},"discredit":{"en":"From dis- + credit.","zh":"从非-+功德.","translation":"machine"},"dislocate":{"en":"From dis- + locate.","zh":"从Dis - +定位。","translation":"machine"},"disrupt":{"en":"Borrowed from Latin disruptus, from disrumpo, commonly dirumpo (“to break or burst asunder”), from dis-, di- (“apart, asunder”) + rumpo (“to break”).","zh":"借自拉丁语的扰动,来自Disrupo, 通常为Dirumpo (\"打破或破裂\"),来自Dis-, di- (\"apart, aunder\") + 朗姆波 (\"打破\").","translation":"machine"},"disruption":{"en":"From Latin disruptionem, from disrumpere. By surface analysis, disrupt + -ion.","zh":"从拉丁语的干扰,从愤怒。通过表面分析,干扰+−离子。","translation":"machine"},"distract":{"en":"Borrowed from Latin distractus, from distrahō (“to pull apart”), from dis- + trahō (“to pull”).","zh":"借自拉丁语分心语, 借自Distrah' (“拉开”),借自Dis- + trah' (“拉”)。","translation":"machine"},"distraction":{"en":"Borrowed from Middle French distraction, from Latin distractio. Equivalent to distract + -ion.","zh":"借自中法分心,拉丁分心,等效以分心+−离子.","translation":"machine"},"eject":{"en":"From Middle French éjecter, from Latin ēiectus, perfect passive participle of ēiciō (“to throw out”), or from ēiectō, the frequentative form of the","zh":"从中法语的éjecter,从拉丁语的'iectus, 完美的被动 participle的'cici ⁇ (\"要扔出去\"),或从'iect ⁇ , 频繁的形式","translation":"machine"},"emission":{"en":"First attested in 1607. From Middle French émission, from Latin ēmissiō (“sending forth”), from ēmittō (“send out”), from ex (“from, out of”) +","zh":"1607年首次证实:来自中法的传教,来自拉丁语的 ⁇ missi ⁇ (\"send out\"),来自 ⁇ mitt ⁇ (\"sent out\"),源于ex (\"sout, out\")+","translation":"machine"},"erupt":{"en":"From Latin eruptus, past participle of ērumpō (“to break out (of), to burst out (from)”), from e (“out”) + rumpō (“to break”).","zh":"从拉丁语喷发,过去'朗普'的 participle'(“(从)爆发,(从)爆发),从e' (从)' (从) + 朗普' ((“从)爆发).","translation":"machine"},"eruption":{"en":"From Middle French éruption, from Latin eruptio.","zh":"从中法语的éruption,从拉丁语的喷发。","translation":"machine"},"evidence":{"en":"From Middle English evidence, from Old French [Term?], from Latin evidentia (“clearness, in Late Latin a proof”), from evidens (“clear, evident”); see evident.","zh":"从中英证据,从古法语[Term?],拉丁语证据(“清楚,用拉丁语作为证明”),从evidens(“清楚,明显”);看明显。","translation":"machine"},"evocative":{"en":"From Latin ēvocātīvus (“pertaining to summoning”). By surface analysis, evoke + -ative.","zh":"从拉丁语 ⁇ vocāt ⁇ vus (“涉及召唤”) ,通过表面分析,引出 + -atimative.","translation":"machine"},"excess":{"en":"From Middle English exces (“excess, ecstasy”), from Old French exces, from Latin excessus (“a going out, loss of self-possession”), from excedere, excessum (“to","zh":"从中英的exces(“excess, ecstasy”),从古法语的exces,从拉丁的exces(“a going out, loss of self-position”),从excidere, excessum(“to”),从excesdere, excressum(“to","translation":"machine"},"excessive":{"en":"From Middle English excessive, excessif, from Old French excessif, from Medieval Latin excessivus, equivalent to excess + -ive.","zh":"从中英过度,过度f,从老法式过度f,从中世纪拉丁过度ivus,相当于过度+−ive.","translation":"machine"},"export":{"en":"From Latin exportare.","zh":"从拉丁出口。","translation":"machine"},"extract":{"en":"Borrowed from Latin extractum, neuter perfect passive participle of extrahō, from ex- (“out of”) + trahō (“to drag”).","zh":"从拉丁语提取物、绝非无端被动的外语组分、从前语组( \" out \" ) + trah( \" to drag \" )中借款。","translation":"machine"},"extraction":{"en":"From Old French estraction, from Medieval Latin extractio.","zh":"出自旧法式节奏,中世纪拉丁语节奏节奏.","translation":"machine"},"extraterrestrial":{"en":"From extra- + terrestrial.","zh":"从外-+陆.","translation":"machine"},"flexibility":{"en":"From French flexibilité, from Late Latin flexibilitās, from Latin flectō (“to bend, curve”). Equivalent to flexible + -ity = flex + -ibility.","zh":"从法语的弹性,从拉丁语的后期弹性,从拉丁的弹性(“弯曲,曲线”),等效到弹性+-ity=弹性+-biculity.","translation":"machine"},"flexible":{"en":"From Middle French flexible, from Latin flexibilis, from flectō (“to bend, curve”). Morphologically flex + -ible.","zh":"从中法柔性,从拉丁语的弹性,从flect ⁇ (“弯曲,曲线”),从莫菲主义的弹性+−可读性.","translation":"machine"},"form":{"en":"From Middle English forme (“shape, figure, manner, bench, frame, seat, condition, agreement, etc.”), borrowed from Old French forme, from Latin fōrma (“shape, figure,","zh":"从中英福梅(“形状,图,方式,长椅,框架,座椅,条件,协议等”)借自法老福梅,从拉丁法尔马(“形状,数字,图,图,图”)借自法老的福梅.","translation":"machine"},"formal":{"en":"From Middle English formel, borrowed from Old French formel, from Latin fōrmālis, from fōrma (“form”); equivalent to form + -al.","zh":"从中英福尔借到旧法兰西福尔,从拉丁语f ⁇ rmālis借到f ⁇ rma (\"form\");相当于形式+−al.","translation":"machine"},"formation":{"en":"From Middle English formacioun, formation, borrowed from Old French formacion, from Latin fōrmātiō, from fōrmō (“form”, verb); see form as verb. Morphologically form","zh":"从中英文的formacioun,形成,借自旧法语的formacion,借自拉丁语的f ⁇ rmāti ⁇ ,借自f ⁇ rm ⁇ (\"form\",动词);将形式看作动词. Morphological form.","translation":"machine"},"geographic":{"en":"From Latin geōgraphicus; see French géographique. By surface analysis, geography + -ic.","zh":"来源于拉丁语地理学;参见法国地理学.按地表分析,地理+-ic.","translation":"machine"},"geological":{"en":"From Renaissance Latin geōlogia + -ical; first attested slightly earlier than geology. By surface analysis, geo- + -logical.","zh":"从文艺复兴时期的拉丁语Geōlogia + -ical;最早的证明略早于地质学.通过地表分析,地-+ - 逻辑学.","translation":"machine"},"geology":{"en":"From geo- + -logy, partly after Renaissance Latin geōlogia, from Ancient Greek γεω- (geō-, “earth”) + Latin -logia (“the study of”), from Ancient","zh":"从地理-+ - 学,部分在文艺复兴时期的拉丁格鲁吉亚之后,从古希腊语- ⁇ -(ge ⁇ -, “Earth”)+拉丁语-logia ((“研究”)),从古希腊语-(Ancient)","translation":"machine"},"geometric":{"en":"From Latin geōmetricus, from Ancient Greek γεωμετρικός (geōmetrikós), from γεωμέτρης (geōmétrēs). By surface analysis, geometer + -ic or geo- + -metric.","zh":"从拉丁格量测定法,从古希腊格量测定法(Geōmetrikós),从格量测定法中得出,按地表分析法,以几何计数+-ic或地理-+-量测定法得出.","translation":"machine"},"geometry":{"en":"From Middle English gemetry, geometrie, from Old French geometrie (modern French géométrie), from Latin geōmetria, from Ancient Greek γεωμετρία (geōmetría, “geometry, land-survey”), from","zh":"从中英几何学,几何学,从旧法兰西几何学(现代法语géométrie),从拉丁语gémmetria学,从古希腊语 ⁇ (Ge ⁇ metria,“几何学,土地调查”),从古希腊学,从古罗马学,从古法国学,到古希腊语,从古希腊文学,从古希腊文,从古希腊的古希腊语,到古希腊的古罗马语,从古罗马语中,从古希腊语言中,从古法国的古希腊语中,从现代的古希腊语géométrie到古希腊语中(Ge ⁇ metria,“地貌学,土地调查),从古希腊古希腊语的古希腊语里,从古希腊文字中,从古古希腊语","translation":"machine"},"geopolitics":{"en":"From geo- + politics, calque of Swedish geopolitik, coined in 1900 by Rudolf Kjellén.","zh":"从地理-+政治,瑞典地缘政治的卡勒克,1900年由Rudolf Kjellén铸造.","translation":"machine"},"geoscience":{"en":"From geo- + science.","zh":"从地理-+科学.","translation":"machine"},"geothermal":{"en":"From geo- + thermal.","zh":"从地-+热.","translation":"machine"},"graph":{"en":"Clipping of graphic formula. From 1878; verb from 1889.","zh":"拼写图形公式,从1878年开始;动词从1889年开始.","translation":"machine"},"graphic":{"en":"From Latin graphicus (“belonging to painting or drawing”), from Ancient Greek γραφικός (graphikós, “belonging to painting or drawing, picturesque, of or for writing;","zh":"从拉丁语图形(“属于绘画或绘画”),从古希腊语(graphikós,“属于绘画或图画,图片,或用于书写;","translation":"machine"},"homophone":{"en":"From French homophone; equivalent to homo- (“same”) + -phone (“sound”).","zh":"发自法国同声调;相当于同声调-(“同声调”) + - phone(“声调”)。","translation":"machine"},"hypothermia":{"en":"From New Latin, from Ancient Greek ὑπο- (hupo-, “under”) + θέρμη (thérmē, “heat”) + -ία (-ía, “feminine suffix”) . By surface analysis, hypo-","zh":"从新拉丁语中,从古希腊语的--(hupo-,“under”)+++(thérm ⁇ ,“heat”)+-+(-ia,“女性后缀”).","translation":"machine"},"illuminate":{"en":"From Middle English illuminaten, borrowed from Latin illūminātus, perfect passive participle of illūminō (“lighten, light up, show off”) (see -ate (verb-forming suffix) for","zh":"从中英灯光,借自拉丁文 hiliminātus, 完美的被动 participle of hilimin ⁇ (\"光,光,亮,炫\") (见 -ate (动词-成形后缀) for","translation":"machine"},"illumination":{"en":"Borrowed from Middle French illumination, from Late Latin illūminātiō, from Latin illumino. Equivalent to illuminate + -ion.","zh":"借用自中法照明,来自Late Latin hispinātiā,来自Latin ilumino. 等效为照明+−离子.","translation":"machine"},"import":{"en":"From Middle English importen, from Old French emporter, importer, from Latin importō (“bring in from abroad, import”, verb), from in (“in, at, on;","zh":"从中英文进口,从旧法式进口商进口,从拉丁文进口(“从国外进口,”动词),从输入(“in, at, o, o];","translation":"machine"},"inaudible":{"en":"From in- + audible.","zh":"从-+声闻.","translation":"machine"},"incredible":{"en":"From Middle English incredible, from Latin incrēdibilis (“that cannot be believed”), from in- (“not”) + crēdibilis (“worthy of belief”), from crēdō (“believe”), equivalent","zh":"从中英难以置信,从拉丁语incr ⁇ dibilis(不能相信),从in-(不能相信)+cr ⁇ dibilis(值得相信),从cr ⁇ d ⁇ (可以相信),等效的","translation":"machine"},"inflection":{"en":"From older inflexion, borrowed from Middle French inflexion, itself borrowed from Latin inflexiōnem (“alteration”, literally “bending”). The English spelling with ⟨ct⟩ is due","zh":"从更古老的inflexion借自中法语inflexion,本身借自拉丁语inflexii ⁇ nem (“alteration,字面意思为“bending ” ). 英文拼写应该用 ⁇ ct ⁇ 来写.","translation":"machine"},"inflexible":{"en":"Borrowed from Middle French inflexible, from Latin īnflexibilis. See also in- + flexible.","zh":"从中法不灵活地借入,从拉丁语 ⁇ nflexibilis 借入。另见 + 灵活。","translation":"machine"},"inform":{"en":"From Middle English informen, enformen, borrowed from Old French enformer, informer (“to train, instruct, inform”), from Latin īnfōrmō (“to shape, form, train, instruct,","zh":"从中英情报,enformen,借自老法兰西情报员,Informer(“训练,指示,通知”),从拉丁语 ⁇ nf ⁇ rm ⁇ ((“以形状,形式,训练,指示,指示,指示),","translation":"machine"},"information":{"en":"From Middle English enformacioun, informacioun, borrowed from Anglo-Norman informacioun, enformation, Old French information, from Latin īnfōrmātiō (“formation, conception; education”), from the participle stem","zh":"来源于中英语的norman findacioun, findaciun, 借用自英法语的nfōrmātiā (“formation, enformation; education”), 来源于participlestround","translation":"machine"},"inject":{"en":"From Latin iniectus, injectus, participle of iniciō, injiciō (“to throw in”), from in- + iaciō (“I throw”).","zh":"从拉丁语iniectus, 注射剂, participle of iniciā, injiciā (\"要扔进去\"),从 + iaci ⁇ (\"我扔\").","translation":"machine"},"injection":{"en":"Borrowed from Middle French injection, from Latin iniectio. The mathematical sense is from French injection, introduced by Nicolas Bourbaki in their treatise Éléments","zh":"从中法注射,拉丁语iniectio中借入. 数学意义来自法国注射,由尼古拉斯·波尔巴基在其论文\"Éléments\"中引入.","translation":"machine"},"inscription":{"en":"Borrowed from Latin īnscrīptiō.","zh":"借自拉丁语 ⁇ nscr ⁇ pti ⁇ 。","translation":"machine"},"inspect":{"en":"From Latin inspectum, past participle of inspicere (“to look into”), from in (“in”) + specere (“to look at”), equivalent to in- + -spect.","zh":"从拉丁文的检查,过去spicere的片段(“调查”),从“in”) + specere(“查看”),相当于-+- spect.","translation":"machine"},"inspection":{"en":"From Middle French, from Old French inspeccion, from Latin īnspectiō (“examination, inspection”), from the verb īnspiciō (“to inspect”), from speciō (“to look at”).","zh":"从中法语,从旧法语的勘察,从拉丁语的'nspecti ⁇ ((检查,检查)),从动词的'nspici ⁇ ((检查)),从speci ⁇ ((查看)).","translation":"machine"},"inspector":{"en":"Borrowed from Latin īnspector, from īnspiciō, equivalent to inspect + -or.","zh":"借自拉丁语 ⁇ nspictor ⁇ nsppi ⁇ ,相当于检查+ -或.","translation":"machine"},"instruct":{"en":"From Latin īnstrūctus, perfect passive participle of īnstruō (“I instruct; I arrange, furnish, or provide”).","zh":"从拉丁语 ⁇ nstr ⁇ ctus, 完美的被动 participle ⁇ nstru ⁇ (\"我指示;我安排,提供,或提供\").","translation":"machine"},"instruction":{"en":"From Middle English instruccioun, from Old French instruccion, from Latin instructio; equivalent to instruct + -ion.","zh":"从中英文instruccioun,从旧法语instruccion,从拉丁语guilio;相当于指示+−ion.","translation":"machine"},"instructor":{"en":"From Latin instructor, equivalent to instruct + -or.","zh":"从拉丁语导师,相当于指示+-或.","translation":"machine"},"interject":{"en":"From Latin interiectus, perfect passive participle of intericiō (“place between”).","zh":"从拉丁语 interiectus, 完美的被动 participle interici ⁇ (\"位置之间\").","translation":"machine"},"interrupt":{"en":"From Middle English interrupten, derived from Latin interruptus, past participle of interrumpere (“to break apart/off, interrupt”), from inter (“between”) + rumpere (“to break”).","zh":"从中英中断,从拉丁语中断,过去 participle of interrumpere (\"要断开/关闭,中断\"),从 inter (\"介于\") + 朗姆佩尔 (\"要断掉\") 中导.","translation":"machine"},"interruption":{"en":"From Middle English interrupcioun, from Old French interrupcion, from Latin interruptio.","zh":"从中英语interrupcioun,从老法語interrupcion,从拉丁语interrupio.","translation":"machine"},"introduce":{"en":"From Middle English introducen, from Old French introduire, from Latin intrōdūcō, ultimately from Proto-Indo-European *h₁énteros (“inner, what is inside”) and *dewk-.","zh":"从中英介绍,从旧法兰西语介绍,从拉丁语介绍,最终从Proto-Indo-European*h1énteros (\"inner, what is inside)\"和*dewk-.","translation":"machine"},"introduction":{"en":"From Middle English introduccioun, introduccyon, borrowed from Old French introduction, itself a borrowing from Latin intrōdūctiōnem, accusative of Latin intrōdūctiō, from intrōdūcō. By","zh":"从中英文introduccioun, introduccyon, 借自旧法式介绍, 本身是借自拉丁文 intr ⁇ d ⁇ cti ⁇ nem, 指责拉丁文 introducción, 借自 intr ⁇ d ⁇ d ⁇ c ⁇ .","translation":"machine"},"invisible":{"en":"From Middle English invisible, from Old French invisible, from Late Latin invīsibilis. Displaced native Old English unġesewenlīċ. Morphologically in- + visible. Piecewise doublet","zh":"从中英隐形,从中法隐形,从Late Latin inv ⁇ sibilis. 流离失所的本地人 Old English un ⁇ esewenl ⁇ . Morphologically in- + 可见. piecwise deplit.","translation":"machine"},"invoke":{"en":"From Middle English *invoken, envoken, borrowed from Old French envoquer, from Latin invocāre (“to call upon”), itself from in- + vocare (“to call”).","zh":"从中英文*invoken, envoken,借自旧法语envoquer,从拉丁语invocāre (\"呼叫\"), 本身从- + vocare (\"呼叫\" ).","translation":"machine"},"kilometer":{"en":"From kilo- + meter.","zh":"从千米+米.","translation":"machine"},"local":{"en":"From Middle English local, from Late Latin locālis (“belonging to a place”), possibly also via Old French local; ultimately from Latin locus (“a","zh":"从中英当地语,从Late Latin locālis (“属地到某地”), 可能也通过旧法兰西当地语; 最终从拉丁语蝗虫 (“a)","translation":"machine"},"locate":{"en":"Borrowed from Latin locātus, perfect passive participle of locō (“to place”) (see -ate (verb-forming suffix)), from locus (“place”) + -ō (verb-forming suffix). Cognate","zh":"从拉丁语locātus借来, 完全被动的loc ⁇ (\"到地方\")(参见-ate(动词-成形后缀)),从蝗虫(\"位置\")+-(动词-形成后缀). Cognate.","translation":"machine"},"location":{"en":"Borrowed from Latin locatio, locationis (“a placing”), from locare (“to place, put, set, let”), from locus (“a place”). Equivalent to locate + -ion.","zh":"借用自Latem locatio, locatis, locadis (“a play”), 借用自 Locard (“to place, place, set, let”), 借用自蝗虫 (“ a place ” ), 借用等效于定位+−离子.","translation":"machine"},"luminary":{"en":"From Late Middle English lūminārī, lūminārīe (“lamp; source of spiritual light, example of holiness; glory”), borrowed from Old French luminarie (“lamp, lights, lighting;","zh":"从中世纪晚期英语 l ⁇ minār ⁇ , l ⁇ mināri ⁇ e (\"灯;灵光之源,圣洁之例;荣耀\"),借自旧法兰西语 luminarie (\"灯,灯,照明\";","translation":"machine"},"luminescent":{"en":"From stem of Latin lumen (“light”) + -escent, equivalent to luminesce + -ent.","zh":"来源于拉丁文lumen (\"light\") + -escent,相当于luminesce + -ent.","translation":"machine"},"luminosity":{"en":"Borrowed from French luminosité or else a native formation from luminous + -ity.","zh":"从法国的luminosité或从光亮+ -ity借来的本土形成.","translation":"machine"},"luminous":{"en":"Borrowed from Middle French lumineus, from Latin lūminōsus.","zh":"借自中法琉球,拉丁语l ⁇ min ⁇ sus.","translation":"machine"},"manicure":{"en":"From French manucure.","zh":"从法曼努尔.","translation":"machine"},"manipulate":{"en":"Back-formation from manipulation.","zh":"从操控的后形.","translation":"machine"},"manual":{"en":"From Middle English manuel, from Anglo-Norman manuel, Old French manual, from Latin manuālis, from manus (“hand”).","zh":"出自中英曼纽尔,出自盎格鲁-诺尔曼曼纽尔,旧法语手册,出自拉丁曼纽利斯,出自马努斯(英语:Manus (hand)).","translation":"machine"},"manufacture":{"en":"From Middle French manufacture, from Old French, from Medieval Latin manūfactūra (“a making by hand”), from manūfactus, a compound of manū factus, manū","zh":"从中法制造,从老法兰西,从中世纪拉丁语的man ⁇ fact ⁇ ra (“手工制作”),从man ⁇ factus,一种由man ⁇ factus,man ⁇ 组成的复合体.","translation":"machine"},"manufacturer":{"en":"From manufacture + -er.","zh":"从制造+ -er.","translation":"machine"},"manuscript":{"en":"From Medieval Latin manūscrīptum (“writing by hand”), a calque of Germanic origin: compare Middle Low German hantschrift (“manuscript, document”), Middle Dutch hantscrift (“manuscript”)","zh":"从中世纪拉丁语man ⁇ scr ⁇ ptum (\"手写\"),一种源于日耳曼语的卡片:比较中低德语汉字(\"manuscript, profile\"),中荷兰语汉字汉字(\"Manucript\").","translation":"machine"},"mediterranean":{"en":"From Latin mediterrāneus (“inland”, from medius (“middle”) + terra (“earth, land”) + -āneus (adjectival suffix)) + -an.","zh":"来源于拉丁语mediterrāneus (\"Inland\",来自medius (\"midle\") + terra (\"土,土地\") + -āneus (adjectival sindix)) + -an.","translation":"machine"},"megaphone":{"en":"From mega- + -phone.","zh":"从巨-+-手机.","translation":"machine"},"meter":{"en":"From Middle English meter, metre, from Old English meter and Old French metre; both from Latin metrum, from Ancient Greek μέτρον (métron).","zh":"来源于中英米表,米表,旧英米表和旧法兰西米表;两者均来源于拉丁米表,古希腊 ⁇ (英语:Ancient Greek QQ (métron)).","translation":"machine"},"metric":{"en":"From French métrique (1864), from New Latin metricus (“pertaining to the system based on the meter”), from metrum (“a meter”); see meter. By","zh":"出自法语métrique(1864年),出自新拉丁语ramus (“包含基于测量仪的系统”),出自metrum (“一个测量仪”);见meter。","translation":"machine"},"metrology":{"en":"From Ancient Greek μέτρον (métron, “measure”) + English -logy.","zh":"来源于古希腊语 QQ(métron,“量度”)+英语 - logy.","translation":"machine"},"microbiology":{"en":"From micro- + biology.","zh":"从微-+生物学.","translation":"machine"},"microchip":{"en":"From micro- + chip.","zh":"从微-+芯片.","translation":"machine"},"microcosm":{"en":"From French microcosme, from Latin microcosmus, from Ancient Greek μικρός (mikrós, “small”) + κόσμος (kósmos, “universe, order”), equivalent to micro- + -cosm.","zh":"来源于法国的微缩缩写,来自拉丁语的微缩写,来自古希腊语的 ⁇ (mikrós,\"小\")+ ⁇ (kósmos,\"单曲,顺序\"),相当于微缩写-+-cosm.","translation":"machine"},"microeconomics":{"en":"From micro- + economics.","zh":"从微-+经济.","translation":"machine"},"microorganism":{"en":"From micro- + organism.","zh":"从微+机体.","translation":"machine"},"microphone":{"en":"From micro- + -phone.","zh":"从微-+-手机.","translation":"machine"},"microplastic":{"en":"From micro- + plastic.","zh":"从微-+塑料.","translation":"machine"},"microscope":{"en":"From New Latin microscopium and Italian microscopio, from Ancient Greek μικρός (mikrós, “small”) + σκοπέω (skopéō, “to look at”), equivalent to micro- +","zh":"来源于新拉丁语的微缩缩写和意大利语的微缩写,来自古希腊语的 ⁇ (mikrós,“小”)+ ⁇ (skop ⁇ ,“看”),相当于微缩写+.","translation":"machine"},"microscopic":{"en":"From microscope + -ic.","zh":"从显微镜+ -ic.","translation":"machine"},"microwave":{"en":"From micro- + wave.","zh":"从微-+波.","translation":"machine"},"motorcycle":{"en":"From motor + cycle, from the Motorcyclette produced in 1897 by the French Werner Frères et Cie.","zh":"从摩托+循环,从法国人维尔纳·弗雷尔(英语:Werner Frères et Cie)于1897年生产的摩托车.","translation":"machine"},"multicultural":{"en":"From multiculture + -al or multi- + cultural.","zh":"从多文化+-al或多文化+.","translation":"machine"},"multifaceted":{"en":"From multi- + facet + -ed.","zh":"从多-+面+-ed.","translation":"machine"},"multilingual":{"en":"From multi- + lingual.","zh":"从多-+语言.","translation":"machine"},"multimedia":{"en":"From multi- + media.","zh":"从多+介质.","translation":"machine"},"multinational":{"en":"From multi- + national.","zh":"从多+国.","translation":"machine"},"multiple":{"en":"From French multiple, itself from Late Latin multiplus.","zh":"从法语多语种, 本身来自Late Latinmultiplus.","translation":"machine"},"multiplication":{"en":"Borrowed from Middle French, from Old French multiplicacion, from Latin multiplicatio, multiplicationem; ~equivalent to multiplicate + -ion.","zh":"从中法,老法式多plicacion,拉丁式多plicatio,乘法;~相当于多复制+−离子.","translation":"machine"},"multiply":{"en":"From Old French multiplier, from Latin multiplicō, from multi (“many”) + plicō (“to fold”). The noun presumably derives from the verb.","zh":"从旧法语乘数,从拉丁语乘数,从多语(“many”) + plic ⁇ (“to flik”) 推算,名词来源于动词。","translation":"machine"},"object":{"en":"From Old French object, from Medieval Latin obiectum (“object”, literally “thrown against”), from obiectus, perfect passive participle of obiciō (“to throw against”), from","zh":"从旧法国物体,从中世纪拉丁语opiectum(“object”,字面意思是“thrrown against”),从obietus, 完美的被动的obicímple ((“tothrow against)),从","translation":"machine"},"objection":{"en":"From Middle French objection, from Old French objeccion, from Latin obiectio. Equivalent to object + -ion.","zh":"从中法反对,从旧法式objecccion,从拉丁式obiectio. Equivalent到object + -ion.","translation":"machine"},"obstruct":{"en":"From Latin past participle stem obstruct- (“blocked up”), from verb obstruere, from ob (“against”) + struere (“pile up, build”).","zh":"源自拉丁语的过去 participlestrike 阻塞- (“堵塞”), 源自动词 obsuthre, 源自obs (“反对”) +sture ((“pile up, build”)).","translation":"machine"},"obstruction":{"en":"From Latin obstructio (“hindrance”), from obstruo (“build against, block, stop”).","zh":"从拉丁语的阻塞语(hindrance),从obstruo语(building against, block,stop).","translation":"machine"},"paragraph":{"en":"From Middle English paragraf, from Middle French paragraphe from Latin paragraphus (“sign for start of a new section of discourse”), from Ancient Greek","zh":"从中英文paragraf,从中法文段落从拉丁语段落(“签署开始新的论述部分”),从古希腊语","translation":"machine"},"perimeter":{"en":"From Latin perimetros, Ancient Greek περίμετρος (perímetros). Equivalent to peri- + meter.","zh":"从拉丁语的perimetros,古希腊语的 ⁇ (perímetros). Equivalation to peri- + meter.","translation":"machine"},"permission":{"en":"From Middle English permision, permission, permissioun, permyssion, from Middle French permission, from Latin permissiō. Equivalent to permit + -ion. Mostly replaced native English","zh":"从中英文的渗透,允许, permission, permyssion,从中法文的渗透,从拉丁语的渗透, 等效到允许 + - 离子。 大部分是取代本地英语 。","translation":"machine"},"permit":{"en":"From Middle English permitten, borrowed from Middle French permettre, from Latin permittō (“give up, allow”), from per (“through”) + mittō (“send”).","zh":"从中英文许可,借自中法文permettre,从拉丁文许可(“give up, relause”),从per(“通过”)+mitt(“send”).","translation":"machine"},"perspective":{"en":"From Middle English perspective, perspectif, attested since 1381, from Old French or Middle French, from the first word of the Medieval Latin perspectiva","zh":"从中英视角,Perspectif,自1381年起被证实,来自老法語或中法語,从中世纪拉丁语的Perspectiva的第一个词.","translation":"machine"},"phone":{"en":"Learned borrowing from Ancient Greek φωνή (phōnḗ, “sound”).","zh":"向古希腊人借钱(ph ⁇ n ⁇ ,“Sound”).","translation":"machine"},"phoneme":{"en":"From Ancient Greek φώνημα (phṓnēma, “sound”), from φωνέω (phōnéō, “to sound”), from φωνή (phōnḗ, “sound”). By surface analysis, phone (“speech sound”) + -eme","zh":"从古希腊语(ph ⁇ n ⁇ ma,“声”),从 ⁇ (ph ⁇ n ,“声 ”),从 ⁇ (h ⁇ n ⁇ ,“声 ” ),从表面分析,电话(“声 ”)+-eme。","translation":"machine"},"phonetic":{"en":"Borrowed from Latin phōnēticus, from Ancient Greek φωνητῐκός (phōnētĭkós). By surface analysis, phone + -etic.","zh":"借用自拉丁语ph ⁇ n ⁇ ticus,古希腊语 ⁇ (ph ⁇ n ⁇ t ⁇ kós),通过表面分析,电话+-etic.","translation":"machine"},"phonology":{"en":"From phono- (prefix denoting sound) + -logy (suffix denoting a branch of learning, or a study of a particular subject).","zh":"从phono-(前缀解音)+ - 语义(后缀解学的一个分支,或特定学科的研究).","translation":"machine"},"photocopy":{"en":"From photo- + copy.","zh":"从相 - + 副本.","translation":"machine"},"photogenic":{"en":"From photo- + -genic.","zh":"从相 - + - 成因.","translation":"machine"},"photograph":{"en":"From photo- + -graph.","zh":"从相-+-图.","translation":"machine"},"photographer":{"en":"From photograph + -er, from Ancient Greek φωτός (phōtós), genitive singular of φῶς (phôs, “light”) (fōs) and γράφω (gráphō, “I write”). By surface","zh":"从照片+-er,来自古希腊语(ph ⁇ tós),genitive单数的 ⁇ (phôs,“光”)和 ⁇ (gráph ⁇ ,“I write ”)。","translation":"machine"},"photographic":{"en":"From photo- + -graphic or photograph + -ic.","zh":"从相-+-图或相+-ic.","translation":"machine"},"photography":{"en":"From French photographie. By surface analysis, photo- + -graphy, together meaning \"drawing with light\" or \"representation by means of lines\", \"drawing\". From φῶς","zh":"从法国摄影机。从表面分析来看,照片-+-图, 统称“用光画”或“用线表示”,“画”。从QQ。","translation":"machine"},"photon":{"en":"From photo- + -on. Coined by American physicist Leonard Troland in 1916 as a unit of light hitting the retina, and later popularized","zh":"从照片-+-on. 1916年被美国物理学家伦纳德·特罗兰(Leonard Troland)用光单位击中视网膜,后来普及.","translation":"machine"},"photoreceptor":{"en":"From photo- + receptor.","zh":"从相 - +受体.","translation":"machine"},"photosynthesis":{"en":"From photo- + synthesis.","zh":"从相-+合成.","translation":"machine"},"portable":{"en":"From Middle English portable, from Middle French portable and Latin portābilis. By surface analysis, port (“to carry”) + -able.","zh":"从中英便携式,从中法便携式和拉丁式portābilis.通过水面分析,port (“to carry”) + -able.","translation":"machine"},"precede":{"en":"From Middle French précéder, from Latin praecēdō, from prae- + cēdō.","zh":"从中法语précéder,从拉丁语praec ⁇ d ⁇ ,从prae-+c ⁇ d ⁇ .","translation":"machine"},"precedent":{"en":"From Middle French, from Old French, from Latin praecēdēns, present participle of praecēdere (“to precede”); See precede.","zh":"从中法语、老法语、拉丁语的praec ⁇ d ⁇ ns, 现为praecıdere ( \" 之前 \" );见前文。","translation":"machine"},"predict":{"en":"Early 17th century, from Latin praedicō (“to mention beforehand”) (perfect passive participle praedictus), from prae- (“before”) + dīcō (“to say”). Equivalent to Germanic","zh":"17世纪早期,从拉丁语praedic ⁇ ((先提到))(完美被动的participle praedictus),从prae- (\"前\") + d ⁇ c ⁇ (\"to say\"). Equivaly to Germanic.","translation":"machine"},"predictable":{"en":"From predict + -able.","zh":"从预测 + -可.","translation":"machine"},"prediction":{"en":"Learned borrowing from Latin praedictiō, praedictiōnis; equivalent to predict + -ion. Compare the Germanic equivalents forespeaking, foretale, foretelling.","zh":"从拉丁语praedictiā, praedictiānis; 等同预测 + - 离子。 比较日耳曼语中的前言,前言,前言。","translation":"machine"},"prescribe":{"en":"Borrowed from Latin praescrībere, from prae- (“before, in front”) and scrībere (“to write”).","zh":"从拉丁语praescrībere、prae-( \" 之前,在前面 \" )和scrīber( \"要写 \" )借款。","translation":"machine"},"prescription":{"en":"Borrowed from Middle French, from Old French prescripcion, from Latin praescriptio (“preface; pretext; something written ahead of time”), from prae- (“pre-, before”) +","zh":"从中法、旧法兰西语、拉丁语praestrifio(“序言;借口;事前写的东西”)借来,从prae-(“前,前”)+","translation":"machine"},"proceed":{"en":"From Middle English proceden, from Old French proceder, from Latin prōcēdō (“to go forth, go forward, advance”), from prō (“forth”) + cēdō (“to","zh":"从中英的音节,从旧法语的音节,从拉丁语的pr ⁇ c ⁇ d ⁇ ((\"走出去,走出去,前进,前进\"),从pr ⁇ (\"forth\") + c ⁇ d ⁇ (\"到\")","translation":"machine"},"process":{"en":"From Middle English proces, from Old French procés (“journey”), from Latin prōcessus (“course, progression”), nominalization of prōcēdō (“proceed, advance”).","zh":"从中英文的proces,从旧法语的procés (\"journey\"),从拉丁语的prãcessus (\"course, processus\"), pràc ⁇ d ⁇ (\"procceed, profile\")的缩写.","translation":"machine"},"procession":{"en":"From Middle English processioun, borrowed from Old French pourciession, from Latin prōcessiō (“a marching forward, an advance, in Late Latin a religious procession”),","zh":"从中英文进程,借自旧法兰西语,从拉丁语(prācessi)中( \" 前进,进步,晚拉丁语为宗教游行\"),","translation":"machine"},"produce":{"en":"From Middle English produce, from Latin prōdūcō (“to lead forth”), from prō- (“forth, forward”) + dūcō (“to lead, bring”).","zh":"从中英文产品,从拉丁语pr ⁇ d ⁇ c ⁇ (\"引出\"),从pr ⁇ - (\"forth, forward\") + d ⁇ c ⁇ ((\"引出,引出\")).","translation":"machine"},"product":{"en":"From Middle English product, from Latin prōductus, perfect participle of prōdūcō, first attested in English in the mathematics sense.","zh":"从中英文产品,从拉丁语pr ⁇ putus, 完美 participle pr ⁇ d ⁇ c ⁇ , 最早在数学意义上的英语证明。","translation":"machine"},"production":{"en":"From Middle English produccioun, from Old French production, from Latin prōductiō, prōductiōnem (“a lengthening, prolonging”). Equivalent to produce + -tion. See produce.","zh":"从中英文的produccioun,从旧法国的producioun,从拉丁语的prōpupiā, pr ⁇ pupi ⁇ nem (“一个延长, 延长” ) 中英文的prucucioun,从老法国的procución,从拉丁语 prāpuciā, prāpupiānem (“ 延长, 延长”) , 等效于生产 + -tion 。见 产品 。","translation":"machine"},"productive":{"en":"Borrowed from Late Latin productivus, equivalent to product + -ive.","zh":"从Late Latin 产物ivus借款,相当于产品+−ive.","translation":"machine"},"project":{"en":"From Latin prōiectus, perfect passive participle of prōiciō (“throw forth, extend; expel”). Compare typologically Russian прики́дывать (prikídyvatʹ), прики́дка (prikídka) (akin to кида́ть (kidátʹ));","zh":"从拉丁语prōiectus, 完美的被动 participle prōici ⁇ (\"推出, 延伸; 驱逐\"). 比较俄罗斯语 ⁇ (prikídyvat ⁇ ), ⁇ (príkídka)(类似于 ⁇ (kidát ⁇ )) ;","translation":"machine"},"projection":{"en":"From either the Middle French projection or its etymon, the Classical Latin prōiectiō (stem: prōiectiōn-), from prōiciō, equivalent to project + -ion. Compare","zh":"从中法的投影或它的标本上看,古典拉丁文的priecti ⁇ (stem:priecti ⁇ n-),从pr ⁇ ci ⁇ ,相当于项目+−ion.","translation":"machine"},"prospect":{"en":"From Middle English prospecte, from Latin prōspectus (“view, sight, prospect; panorama”), from prōspiciō (“to look forward”) + -tus (suffix forming action nouns), from","zh":"从中英文前景,从拉丁语prōspectus (“view, sight, people; planorama”),从prōspiciý (“to look forward”) + -tus (后缀形成动作名词),从","translation":"machine"},"prospective":{"en":"From Middle French prospectif, from Late Latin prospectivus. See more at English prospect.","zh":"从中法前景,从晚拉丁前景。请参看英文前景。","translation":"machine"},"provoke":{"en":"Borrowed from Middle French provoquer, from Old French, from Latin prōvocāre. Doublet of provocate.","zh":"借自中法代言人,旧法兰西语代言人,拉丁语代言人(prōvocāre),双重代言人.","translation":"machine"},"psychiatrist":{"en":"From psychiatry + -ist.","zh":"从精神病学+ -ist.","translation":"machine"},"psychiatry":{"en":"Borrowed from French psychiatrie. First attested in 1846.","zh":"从法国精神病学那里借来的 1846年第一次证明","translation":"machine"},"psychic":{"en":"From Ancient Greek ψυχικός (psukhikós, “relative to the soul, spirit, mind”). Earlier referred to as \"psychical\"; or from Ancient Greek ψυχή (psukhḗ, “soul,","zh":"从古希腊语(psukhikós,“与灵魂,精神,心灵的关系”) 早期称为\"精神\";或从古希腊语(psukkhóós,“soul,","translation":"machine"},"psychological":{"en":"From psychology + -ical.","zh":"从心理学 + - 逻辑学.","translation":"machine"},"psychologist":{"en":"From psycholog(y) + -ist.","zh":"从精神学(y) + -ist.","translation":"machine"},"psychology":{"en":"From French psychologie, from Renaissance Latin psychologia, from Ancient Greek ψυχή (psukhḗ, “soul”) + -λογία (-logía, “study of”), equivalent to psycho- + -logy.","zh":"来源于法国心理学,来源于文艺复兴时期的拉丁心理学,来源于古希腊语 ⁇ (psukh ⁇ , “soul”) + - ⁇ (-logía, “研究”),相当于心理-+ - 学.","translation":"machine"},"psychosomatic":{"en":"From psycho- + somatic.","zh":"从精神 - + 生理。","translation":"machine"},"psychotherapy":{"en":"From psycho- + therapy.","zh":"从心理 - +治疗。","translation":"machine"},"recede":{"en":"Inherited from Middle English receden, from Middle French receder and its etymon Latin recedere (“to withdraw; to go back”), from re- + cedere","zh":"继承自中英退位,中法退位和它的英式拉丁退位(\"退位;退位),从复-+割位.","translation":"machine"},"recession":{"en":"Borrowed from Latin recessiō, from recēdō (“recede, retreat”), from re- (“back”) + cēdō (“to go”). By surface analysis, recess + -ion.","zh":"从拉丁语sunci ⁇ 、 recaded ⁇ (“接收,撤退”)和 re-(“返回”) + c ⁇ d ⁇ (“去”)。","translation":"machine"},"reconstruct":{"en":"From re- + construct.","zh":"从复-+构造.","translation":"machine"},"recyclable":{"en":"From recycle + -able.","zh":"从再循环+ -可回收。","translation":"machine"},"recycle":{"en":"From re- + cycle.","zh":"从复-+周期.","translation":"machine"},"reduce":{"en":"From Middle English reducen, from Old French reduire, from Latin redūcō (“reduce”); from re- (“back”) + dūcō (“lead”). See duke, and compare with","zh":"从中英文减法,从旧法语减法,从拉丁语减法,从复语减法,再从回语减法。","translation":"machine"},"reduction":{"en":"From Middle English reduccion, a borrowing from Old French reducion, from Latin reductiō, reductiōnem. Equivalent to reduce + -tion.","zh":"从中英reduccion, 借自旧法语的reducion,从拉丁语repuctiā, repuctiānem. Equivalent to dump + -tion.","translation":"machine"},"reflect":{"en":"From Old French reflecter (“to bend back, turn back”), from Latin reflectō (“to reflect”), from re- (“again”) + flectō (“to bend, to curve”).","zh":"从旧法国反射器(“向后弯曲,向后弯曲”),从拉丁反射器(“反射”),从再反射器(“又”)+反射器(“弯曲,向下弯曲”)。","translation":"machine"},"reflection":{"en":"From Middle English refleccion, refleccioun, refleccioune, reflection, from Middle French reflection, reflexion, and its source Late Latin reflexiō, from the participle stem of","zh":"从中英文 refleccion, reflecccioun, refleccioune, 反射,从中法反射,反射, 及其源头 晚拉丁反射,从participle rounds","translation":"machine"},"reflex":{"en":"From Late Latin reflexus, past participle of reflectere (“to bend back”), equivalent to re- + flex. Photography sense is from noun sense meaning","zh":"从后拉丁反射,过去反射(\"向后弯曲\")的片段,相当于再-+弹性. 摄影感是名词意义.","translation":"machine"},"reform":{"en":"From Middle English reformen, from Old French reformer, from Latin reformo, reformare. As a noun since 1660s, from French réforme.","zh":"出自中英改革派,法兰西老改革派,拉丁改革派,改革派,作为1660年代起的名词,出自法兰西语réforme.","translation":"machine"},"reject":{"en":"From Late Middle English rejecten, from Latin reiectus, past participle of reicere (“to throw back”), from re- (“back”) + iacere (“to throw”). Displaced","zh":"从中晚期英语的拒绝语,从拉丁语Reiectus,过去Reicere的participle (\"tothrow back\"),从re- (\"back\") + iacere (\"to srow\") 流离语.","translation":"machine"},"rejection":{"en":"From French réjection or directly from Latin reiectiōnem, accusative of Latin reiectiō. Displaced native Old English āworpennes (literally “thrown-out-ness”).","zh":"从法语的réjection或直接从拉丁语reiectiōnem, 指责拉丁语reiecti ⁇ . 流离失所的本地老英语āworpennes(字面意思是\"thrown-out-ness\").","translation":"machine"},"relocate":{"en":"From re- + locate.","zh":"从复-+定位.","translation":"machine"},"relocation":{"en":"From re- + location.","zh":"从复-+位置.","translation":"machine"},"report":{"en":"From Middle English reporten, from Anglo-Norman reporter, from Latin reportāre (“to carry back, return, remit, refer”), from re- + portāre.","zh":"出自中英报道,来自盎格鲁-诺曼记者,来自拉丁报道āre (\"要背,回,寄,参考\"),来自re- + portāre.","translation":"machine"},"reporter":{"en":"From Middle English reportour, from Old French reporteur; equivalent to report + -er.","zh":"从中英文报告,从旧法语报告人;相当于报告+-er.","translation":"machine"},"respectful":{"en":"From respect + -ful.","zh":"从尊重+-ful.","translation":"machine"},"retract":{"en":"From Late Middle English retracten, retract (“to absorb, draw in”), from Latin retractus (“withdrawn”), the perfect passive participle of Latin retrahō (“to draw","zh":"从后期中英文的收回,收回(“吸收,引出”),从拉丁语的收回(“撤回”),拉丁语的完美被动部分(“引出”)","translation":"machine"},"retrospect":{"en":"Borrowed from Latin retrōspectum, from retrōspicio (“to look back at”), equivalent to retro- + -spect. Compare review.","zh":"从拉丁语的retrāspectum,从retr ⁇ spicio (\"回顾\") 借来,相当于retro- + - spect. 比较审查.","translation":"machine"},"revise":{"en":"Borrowed from Middle French réviser, from Latin revīsō, from re- + vīsō (“examine”), frequentative of videō (“see”).","zh":"从中法语réviser、拉丁语rv ⁇ s ⁇ 、re-+v ⁇ s ⁇ (“审查”)借来的,经常用来维系(“见”)。","translation":"machine"},"revision":{"en":"From re- + vision.","zh":"从复-+观.","translation":"machine"},"revoke":{"en":"Borrowed from Middle French révoquer, from Latin revocare, from re- + voco, vocare. Doublet of revocate.","zh":"借自中法révoquer,拉丁语revocare,从re-+voco,vocare. Doublet of revocuse.","translation":"machine"},"rupture":{"en":"Borrowed from Middle French rupture, or its source, Latin ruptūra (“a breaking, rupture (of a limb or vein)”) and Medieval Latin ruptūra (“a","zh":"从中法断裂或其来源借来的拉丁文ruptára(“断裂、断裂(肢体或静脉))和中世纪拉丁文ruptra(“a)","translation":"machine"},"spectacle":{"en":"From Middle English spectacle, from Middle French spectacle, from Latin spectāculum (“a show, spectacle”), from spectō (“to see, behold”), frequentative of speciō (“to","zh":"从中英眼镜从中法眼镜从拉丁语spectāculum (\"a show, case\")从Spect ⁇ (\"to see, seen\")从中英眼镜,从中法眼镜,从拉丁语specāculum(\"a shot, case\",\"the spect ⁇ \")从中法眼镜,从中英眼镜(\"to\")从中美眼镜,从中英镜头(\"to\"to\")从中看,从中英眼镜('to\"to\"to)从中看\"speci ⁇ \"的频率(\"to\"a scentāculum\",\"a)从中看,从斯奇奇奇奇\"(\"to\" to\"to\")到\".","translation":"machine"},"spectator":{"en":"Borrowed from Latin spectātor, from frequentative verb spectō (“watch”), from speciō (“look at”). Equivalent to spectate + -or. Doublet of speculator.","zh":"借用拉丁语spectātor, 频繁动词spect ⁇ (\"watch\"), speci ⁇ (\"看\"), 等同于spect ⁇ + - 或. 双重投机者.","translation":"machine"},"structural":{"en":"From structure + -al, 19th century.","zh":"从结构+ -al, 19世纪.","translation":"machine"},"structure":{"en":"From Middle French structure, from Latin structūra (“a fitting together, adjustment, building, erection, a building, edifice, structure”), from struere, past participle structus (“pile","zh":"从中法结构,从拉丁语structára(“一个组合,调整,建筑,勃起,一个建筑,建筑,结构”),从斯特雷,过去participle structus(“pile),","translation":"machine"},"subaquatic":{"en":"From sub- + aquatic.","zh":"从子+水生.","translation":"machine"},"subject":{"en":"From Middle English subget, from Old French suget, from Latin subiectus (“lying under or near, adjacent, also subject, exposed”), as a noun, subiectus","zh":"从中英文子集,从老法式suget,从拉丁语子集((位于下方或近处,相邻,也位于下方,暴露)),作为一个名词,子集","translation":"machine"},"subjective":{"en":"From Latin subiectīvus, equivalent to subject + -ive.","zh":"从拉丁语subiectívus,相当于主语+−ive.","translation":"machine"},"submission":{"en":"From Middle English submissioun, from Old French soubmission, from Latin submissio, from submitto.","zh":"从中英文submission,从旧法语soubmission(法语:Old French soubmission),从拉丁语submissio,从顺化.","translation":"machine"},"submit":{"en":"From Middle English submitten, borrowed from Latin submittere, infinitive of submittō (“place under, yield”), from sub (“under, from below, up”) + mitto (“to","zh":"从中英文提交书中,从拉丁文提交书中借到 \" 提交书 \" ( \" 位置以下,产量 \" ),从子( \" 下,从下,上 \" )+ mitto ( \"到 \" )","translation":"machine"},"subscribe":{"en":"From Middle English subscriben, subskryben, from Latin subscrībere (“write beneath”). By surface analysis, sub- + scribe. Compare its native English equivalent underwrite.","zh":"从中英文订阅者 subskryben从拉丁文subscribere (“ write under”) 读取表层分析, sub- + complete 。 比较其本土英语等效的下方文字 。","translation":"machine"},"subscription":{"en":"From Latin subscriptiō; by surface analysis, sub- + script + -ion. All senses reflect (either literally or figuratively) the notion of signing one's","zh":"从拉丁文下标;通过表面分析,下标+脚本+−离子。所有感官(无论是字面上还是象征上)都反映签名的概念。","translation":"machine"},"subterranean":{"en":"From Latin subterrāneus + -an. Compare subterrane and subterraneous.","zh":"来源于拉丁语的亚terāneus + -an. 比较亚terrane和亚terraness.","translation":"machine"},"subtract":{"en":"Borrowed from Latin subtractus, perfect passive participle of subtrahō (“to draw from beneath; withdraw, remove”); from sub (“under”) + trahō (“to draw, pull,","zh":"从拉丁文减法中借款, 完全被动地从底部( \"从下面提取; 撤回、 移除 \" );从底部( \"在下面 \" ) + trah' ( \"从下面提取、拉,","translation":"machine"},"successful":{"en":"From success + -ful.","zh":"从成功+-ful.","translation":"machine"},"successfully":{"en":"From successful + -ly.","zh":"从成功+-ly.","translation":"machine"},"successive":{"en":"From Latin succedere (“to succeed in”).","zh":"从拉丁语suscedere(\"在\"中成功).","translation":"machine"},"successor":{"en":"From Anglo-Norman successour, from Latin successor.","zh":"来自盎格鲁-诺尔曼成功者,来自拉丁继任者.","translation":"machine"},"supervise":{"en":"Borrowed from Medieval Latin supervisus, from supervidere, from Latin super + videre. Doublet of survey.","zh":"借用自中世纪拉丁语的超级监听,超级监听,拉丁语的超级+Videre. Doublet of survey.","translation":"machine"},"supervisor":{"en":"Attested since the 15th century C.E.; from Middle English supervisor, supervisour, supervysor, supervysour, from Latin supervīsor, from supervideō, in turn from super +","zh":"从15世纪开始接受测试;从中英监制,监制,超能,超能,从拉丁超能,从超能,再从超能,转而从超能+.","translation":"machine"},"support":{"en":"From Middle English supporten, from Old French supporter, from Latin supportō.","zh":"从中英支持,从老法兰西支持者,从拉丁支持 ⁇ .","translation":"machine"},"supportive":{"en":"From support + -ive.","zh":"从支持 + -ive.","translation":"machine"},"suspect":{"en":"From Old French suspect, from Latin suspectus, perfect passive participle of suspiciō (“mistrust, suspect”), from sub (“under”), + speciō (“watch, look at”).","zh":"从法国老嫌疑人,从拉丁嫌疑人, 完美的被动 部分suspici ⁇ (“Mistust, suspect”),从子(“under”), + speci ⁇ (“Watch, look at”).","translation":"machine"},"symmetry":{"en":"From Latin symmetria, from Ancient Greek συμμετρία (summetría), from σύμμετρος (súmmetros, “symmetrical”), from σύν (sún, “with”) + μέτρον (métron, “measure”). By surface analysis,","zh":"从拉丁语的对称,从古希腊语的QQ(summería),从XX(súmmetros,“对称”),从XQ(sún,“与”)+X(métron,“计量”),通过表面分析,","translation":"machine"},"symphony":{"en":"From Middle English symphonye, from Old French simphonie, from Latin symphonia, from Ancient Greek συμφωνία (sumphōnía). By surface analysis, sym- + -phony. Doublet","zh":"出自中英交响曲,古法语simphonie,拉丁语simphonia,古希腊语 ⁇ (sumph ⁇ n ⁇ a),按表面分析,sym-+-phony. Doublt.","translation":"machine"},"synchronize":{"en":"From Ancient Greek συγχρονίζω (sunkhronízō), equivalent to syn- + chrono- + -ize.","zh":"来源于古希腊语 QQ(sunkhroníz ⁇ ),相当于syn- + chrono- + - ize.","translation":"machine"},"telecommute":{"en":"From tele- + commute.","zh":"从电传 - +通勤.","translation":"machine"},"telegraph":{"en":"Borrowed from French télégraphe, equivalent to tele- (“far, distant”) + -graph (“writing”), suggested as a new name for Claude Chappe's overland semaphore network","zh":"从法国的télégraphe借款,相当于远程(“远,远”)+-graph (“书面”),作为克劳德·查普陆地血浆网络的新名称。","translation":"machine"},"telemetry":{"en":"From tele- + -metry.","zh":"从远程-+-度量.","translation":"machine"},"telepathy":{"en":"From tele- + -pathy.","zh":"从远程+ - 冷漠。","translation":"machine"},"telephone":{"en":"The noun is derived from tele- (prefix meaning ‘from a distance’) + -phone (suffix denoting a device which makes a sound), modelled after","zh":"名词来源于远程(前缀意为`距离 ' )+-手机(后缀表示发出声音的装置),其模式是:","translation":"machine"},"telescope":{"en":"From tele- + -scope. From Latin tēlescopium, from Ancient Greek τηλεσκόπος (tēleskópos, “far-seeing”), from τῆλε (têle, “afar”) + σκοπέω (skopéō, “to look at”).","zh":"从远程+-镜像,来自拉丁语的t ⁇ lescopium,来自古希腊语的Q ⁇ (t ⁇ leskópos,“远视”),来自 ⁇ (têle,“afar”)+ ⁇ (skop ⁇ ,“看”)。","translation":"machine"},"television":{"en":"From tele- + vision. First attested in 1900, probably influenced by French télévision from Constantin Perskyi's 1900 paper that was unpublished but presented","zh":"从远程-+视觉. 1900年首次证实, 可能受来自君士坦丁·佩尔斯基1900年论文的法语télévision的影响,","translation":"machine"},"terrain":{"en":"Unadapted borrowing from French terrain, from Latin terrenum (“land, ground”), neuter of terrenus (“consisting of earth”), from terra (“earth”).","zh":"未经调整从法国地形、拉丁地形(“陆地,地面”)、地铁(“由地球构成”)和地铁(“大地”)借款。","translation":"machine"},"terrarium":{"en":"From Latin terra (“earth”) + -arium, by analogy with aquarium.","zh":"从拉丁语terra (\"土\") + -arium,通过类推与水族馆.","translation":"machine"},"terrestrial":{"en":"From Middle English terrestrialle, from terrestre or Latin terrestris, from terra (“land, earth, ground”), with the suffix -al.","zh":"从中英兰德尔语,从terrestre或拉丁特雷斯特里语,从terra语(\"土地,土,地\"),后缀-al.","translation":"machine"},"territory":{"en":"Inherited from Middle English territorie, from Latin territōrium.","zh":"继承自中英特立托里,拉丁特立托里姆.","translation":"machine"},"thermal":{"en":"From French thermal, from New Latin *thermalis, from Ancient Greek θέρμη (thérmē, “heat”), from Proto-Indo-European *gʷʰer- (“to heat, warm”).","zh":"发自法国热,来自新拉丁语*thermalis,来自古希腊语 ⁇ (thérm ⁇ ,\"热\"),来自普罗托-印欧语*gwher-(\"去热,温暖\").","translation":"machine"},"thermodynamics":{"en":"From thermo- + dynamics. First attested in the 1850s.","zh":"从热力+动力学,1850年代首次证实.","translation":"machine"},"thermometer":{"en":"Borrowed from French thermomètre; equivalent to thermo- + -meter.","zh":"借用自法国热量计;相当于热量-+-米。","translation":"machine"},"thermostat":{"en":"From thermo- + -stat.","zh":"从热-+-stat.","translation":"machine"},"transcript":{"en":"From Latin transcriptum, from transcribere.","zh":"从拉丁语的笔录,从转写。","translation":"machine"},"transform":{"en":"From Middle English transformen, from Old French transformer, from Latin transformo, transformare, from trans (“across”, preposition) + forma (“form”).","zh":"从中英变速器,从老法式变速器,拉丁变速器,变速器,转速器(\"across, preposition\")+ forma (\"form\").","translation":"machine"},"transformation":{"en":"Inherited from Middle English transformacioun, from Middle French, from Ecclesiastical Latin trānsfōrmātiō. Morphologically transform + -ation.","zh":"继承自中英变形金刚,中法,拉丁文tānsfōrmāti ⁇ . 摩法变形金刚+− ⁇ .","translation":"machine"},"transmission":{"en":"Borrowed from Latin transmissionem (accusative of transmissio), from transmittere.","zh":"从拉丁语传输器(英语:cusacus of transmissio),从传输器中借款.","translation":"machine"},"transmit":{"en":"From Middle English transmitten, borrowed from Latin trānsmittō (“transmit”, verb, literally “across-send”).","zh":"从中英文传输,借自拉丁文tānsmitt ⁇ (“发送”,动词,字面意思是“交叉端”).","translation":"machine"},"transmitter":{"en":"From transmit + -er.","zh":"从传输 + -er.","translation":"machine"},"transport":{"en":"Inherited from Middle English transporten, a borrowing from Old French transporter (“carry or convey across”), from Latin trānsportāre (“to carry over, take across,","zh":"继承自中英运输公司,从旧法国运输公司(“运输或传送过”)借款,从拉丁语tānsportāre(“承接,承接过”,","translation":"machine"},"transportation":{"en":"From transport + -ation.","zh":"从运输+ - 配电.","translation":"machine"},"uniform":{"en":"Borrowed from Middle French uniforme, from Latin uniformis.","zh":"借自中法制服,拉丁制服.","translation":"machine"},"verdict":{"en":"From Middle English verdit, from Anglo-Norman verdit (> Medieval Latin veredictum), from veir (“true”) + dit (“saying”); possibly a calque of a Germanic","zh":"发自中英文verdit,发自盎格鲁-诺曼文verdit (>中世纪拉丁文vereditum),发自维尔 (\"real\") + dit (\"saying\");可能为日耳曼语的一个卡片.","translation":"machine"},"video":{"en":"From the root vide of Latin videō (“to see”) + -o, formed in analogy to audio.","zh":"从拉丁语的根维德(英语:root vide) + -o(\"to see\"),形成于类比到音频.","translation":"machine"},"visible":{"en":"From Middle English visible, from Old French visible, from Late Latin visibilis (“that may be seen”), from Latin videre (“to see”), past participle","zh":"从中英文可见,从老法式可见,从Late Latin visibilis(“可以看见”),从拉丁维德((“看”),过去participle","translation":"machine"},"vision":{"en":"From Middle English visioun, from Anglo-Norman visioun, from Old French vision, from Latin vīsiō (“vision, seeing”), noun of action from the perfect passive","zh":"从中英维尼翁,从盎格鲁-诺尔曼维尼翁,从老法兰西的视野,从拉丁文 v ⁇ si ⁇ (\"视觉,看见\"),从完美被动的动作名词","translation":"machine"},"visual":{"en":"From Middle English visual, from French visuel, visual and directly from Late Latin vīsuālis (“of sight”), from vīsus (“sight, vision”) + -ālis (“adjective","zh":"从中英视觉,从法语粘土,视觉和直接从Late Latin v ⁇ suālis (\"of sight\"),从v ⁇ sus (\"视觉,视觉\") + -ālis ((形容式))","translation":"machine"},"vocabulary":{"en":"Learned borrowing from Medieval Latin vocābulārium. Doublet of vocabularium.","zh":"向中世纪拉丁语借书 词汇的双倍","translation":"machine"},"vocation":{"en":"From Middle English vocacioun, from Old French vocation, from Latin vocātiō.","zh":"从中英文vocacioun,从旧法语的事业,从拉丁语vocātiā。","translation":"machine"}};
